# Apply shift (+2,-6) + forward to test input correctly
test_grid = [[int(x) for x in l.split()] for l in test_input_str.strip().split('\n')]
bg = 3
dr, dc = 2, -6

output_grid = [row[:] for row in test_grid[:]]  # forward copy (same values)
for r in range(17):
    for c in range(23):
        val = test_grid[r][c]
        if val != bg:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 17 and 0 <= nc < 23:
                output_grid[nr][nc] = val

# Validate
eight_count = sum(1 for r in range(17) for c in range(23) if output_grid[r][c] == 8)
print(f"8 count: {eight_count}")
eight_pos = sorted([(r,c) for r in range(17) for c in range(23) if output_grid[r][c] == 8])
print(f"8 positions: {eight_pos}")

# Handle overlaps - some positions get overwritten
print("\nOverlap check - when pixels go to same position:")
num_dst = {}
for r in range(17):
    for c in range(23):
        val = test_grid[r][c]
        if val != bg:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 17 and 0 <= nc < 23:
                key = (nr, nc)
                if key not in num_dst:
                    num_dst[key] = []
                num_dst[key].append((val, test_grid[r][c]))

for key, vals in num_dst.items():
    if len(vals) > 1:
        print(f"  {key}: {vals}")

# Create and save submission
import json
out_rows = [' '.join(str(x) for x in row) for row in output_grid]
grid_array = [[int(x) for x in row.split()] for row in out_rows]

with open('/home/ubuntu/runs/paper/qwen-h-u1-turns/play/users/u000/system/state/workspace/submission.json', 'w') as f:
    json.dump(grid_array, f)

print(f"\nSaved shift (2,-6) + forward to submission.json")
